#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_new_with_string_length_valid_string_and_length(void) {
    // Setup: create a valid string and length
    char test_str[] = "hello world";
    size_t test_len = 5; // Only use "hello"

    // Test: call the function under test
    buffer_t *buf = buffer_new_with_string_length(test_str, test_len);

    // Assertions
    TEST_ASSERT_NOT_NULL(buf);
    TEST_ASSERT_EQUAL_PTR(test_str, buf->data);
    TEST_ASSERT_EQUAL_PTR(test_str, buf->alloc);
    TEST_ASSERT_EQUAL(test_len, buf->len);

    // The buffer does not copy or own the string, so content is not guaranteed to be null-terminated.
    // We can check that the first 'len' bytes match the input string.
    TEST_ASSERT_EQUAL_MEMORY(test_str, buf->data, test_len);

    // Cleanup: only free the buffer struct, not the string
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_new_with_string_length_valid_string_and_length);
    return UNITY_END();
}

